def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def clamp_dir(a, b):
        return sgn(b - a)

    def pos_list(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        return None

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos_list(observation.get("self_position")) or [0, 0]
    op = pos_list(observation.get("opponent_position")) or [sx, sy]
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    def dist2(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(target):
        return [clamp_dir(sx, target[0]), clamp_dir(sy, target[1])]

    def step_away(target):
        return [clamp_dir(target[0], sx), clamp_dir(target[1], sy)]

    def best_target(items, prefer_max=False):
        good = []
        for it in items or []:
            p = pos_list(it)
            if p is not None:
                good.append(p)
        if not good:
            return None
        if prefer_max:
            return max(good, key=lambda p: dist2([sx, sy], p))
        return min(good, key=lambda p: dist2([sx, sy], p))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(op)
        corners = []
        if gw and gh:
            corners = [[0, 0], [0, gh - 1], [gw - 1, 0], [gw - 1, gh - 1]]
        if not corners:
            corners = [[-10, -10], [-10, 10], [10, -10], [10, 10]]
        return step_toward(max(corners, key=lambda c: dist2(c, op)))

    if env == "territory_control":
        for key in ("unclaimed_cells", "neutral_cells", "opponent_territory", "frontier", "targets"):
            t = best_target(observation.get(key) or [], prefer_max=False)
            if t is not None:
                return step_toward(t)
        return step_toward(op)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = best_target(resources, prefer_max=False)
    if target is not None:
        return step_toward(target)

    # Fallbacks: pressure opponent, else drift toward center if known.
    if gw and gh:
        center = [gw // 2, gh // 2]
        if [sx, sy] != center:
            return step_toward(center)
    return step_toward(op)

